import base64,hashlib,json,os,stat
from pathlib import Path
root=Path("/data/yanruj/EvolveSWDB_runs/probata-resume-20261016-t28-initialized-cold-04af74c1-v9")
assert not os.path.lexists(root), "fresh cold context already exists"
rows = json.loads(base64.b64decode(''))
assert len(rows)==10 and sum(row["bytes"] for row in rows)==238404
root.mkdir(mode=0o700);control=root/"control";control.mkdir(mode=0o700)
result=[]
for row in rows:
 assert Path(row["name"]).name==row["name"]
 b=base64.b64decode(row["base64"],validate=True)
 assert len(b)==row["bytes"] and hashlib.sha256(b).hexdigest()==row["sha256"]
 p=control/row["name"]
 with p.open("xb") as stream:stream.write(b)
 assert stat.S_ISREG(p.lstat().st_mode) and p.resolve()==p
 assert hashlib.sha256(p.read_bytes()).hexdigest()==row["sha256"]
 result.append({"path":str(p),"bytes":row["bytes"],"sha256":row["sha256"]})
assert {p.name for p in control.iterdir()}=={r["name"] for r in rows}
assert not os.path.lexists(root/"reader-source-cache")
print(json.dumps({"status":"STAGED_CONTEXT_ONLY_READER_NOT_EXECUTED","files":result},sort_keys=True))
